// Grab the incoming webhook request body directly
const inputItem = $input.item.json;
const args = inputItem.body?.message?.toolCalls?.[0]?.function?.arguments || {};

// Target date passed by Vapi (fallback to today if empty)
const requestedDateStr = args.date || new Date().toISOString().split('T')[0];

// Define start and end of that target day in ISO format for the calendar node
const timeMin = new Date(`${requestedDateStr}T00:00:00Z`).toISOString();
const timeMax = new Date(`${requestedDateStr}T23:59:59Z`).toISOString();

return [{
  json: {
    requestedDate: requestedDateStr,
    timeMin: timeMin,
    timeMax: timeMax
  }
}];

// Retrieve Google Calendar events (will be an empty array [] if the day is completely free)
const events = $input.all();
const requestedDateStr = $('Parse Requested Date & Set Time Range').item.json.requestedDate;

// Define your standard business hours slots (9 AM - 4 PM)
const standardSlots = ["09:00", "10:00", "11:00", "13:00", "14:00", "15:00", "16:00"];

// Extract busy event start times safely
const busyTimes = events
  .filter(e => e.json && e.json.start)
  .map(e => e.json.start.dateTime || e.json.start.date || "");

// Filter out slots that overlap with busy times
const availableSlots = standardSlots.filter(slot => {
  const slotISO = `${requestedDateStr}T${slot}`;
  return !busyTimes.some(busy => busy.includes(slotISO));
});

return [{
  json: {
    requestedDate: requestedDateStr,
    availableSlots: availableSlots.join(', ') || "No open slots",
    hasSlots: availableSlots.length > 0
  }
}];
